set-variable.value:
@{
        try {
            var ticket = context.Request.Headers.GetValueOrDefault("X-Core-Call-Ticket", "");
            var callId = context.Request.MatchedParameters.GetValueOrDefault("callId", "");
            if (context.Request.Url.Query.Count != 0 || ticket.Length > 4096 || !System.Text.RegularExpressions.Regex.IsMatch(callId, @"^[A-Za-z0-9_-]{1,160}$")) { return false; }
            var parts = ticket.Split('.');
            if (parts.Length != 2) { return false; }
            var key = System.Text.Encoding.UTF8.GetBytes("{{core-realtime-ticket-key}}");
            string expected;
            using (var hmac = new System.Security.Cryptography.HMACSHA256(key)) {
                expected = Convert.ToBase64String(hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(parts[0]))).TrimEnd('=').Replace('+', '-').Replace('/', '_');
            }
            if (expected.Length != parts[1].Length) { return false; }
            var difference = 0;
            for (var i = 0; i < expected.Length; i++) { difference |= expected[i] ^ parts[1][i]; }
            if (difference != 0) { return false; }
            var encoded = parts[0].Replace('-', '+').Replace('_', '/');
            encoded += new string('=', (4 - encoded.Length % 4) % 4);
            var payload = Newtonsoft.Json.Linq.JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(encoded)));
            var decision = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["gatewayDecision"]);
            var settings = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["gatewayOperationConstraint"]);
            /* 所有者は入口で検証した購読またはユーザーです。認証方式をまたいで移しません。 */
            var userOwner = (string)decision["method"] == "user";
            if ((bool?)decision["allowed"] != true) { return false; }
            var subscriptionId = "";
            if ((string)decision["method"] == "subscriptionKey") {
                if (context.Subscription == null || String.IsNullOrWhiteSpace(context.Subscription.Id)
                    || (string)decision["callerId"] != "subscription:" + context.Subscription.Id) { return false; }
                subscriptionId = context.Subscription.Id;
            } else if (userOwner) {
                if (context.Subscription != null || !context.Variables.ContainsKey("gatewayEntraAuthenticationValidated")
                    || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]) { return false; }
                var user = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
                Guid tenant, principal;
                if (!Guid.TryParse((string)user["tenantId"], out tenant) || tenant == Guid.Empty
                    || !Guid.TryParse((string)user["principalId"], out principal) || principal == Guid.Empty) { return false; }
                var caller = "user:" + tenant.ToString("D") + ":" + principal.ToString("D");
                if ((string)decision["callerId"] != caller || (string)user["callerId"] != caller
                    || (string)decision["verifiedTenantId"] != tenant.ToString("D")
                    || (string)decision["verifiedPrincipalId"] != principal.ToString("D")) { return false; }
            } else { return false; }
            var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            return (int?)payload["v"] == (userOwner ? 4 : 3) && (string)payload["callId"] == callId
                && (string)payload["subscriptionId"] == subscriptionId
                && (string)payload["callerId"] == (string)decision["callerId"]

                && (long?)payload["exp"] > now && (long?)payload["exp"] <= now + (int)settings["sessionTtlSeconds"];
        } catch { return false; }
    }
